// Concat auto-catalogued stubs from the Gemini-corpus import. These fill
// out the long tail of Release 01 PDFs we haven't hand-curated yet;
// they're flagged auto: true so the UI can dim or section them. Promote
// a stub by writing a fully-curated entry in RAW above and removing it
// from events-auto.js.
import { EVENTS_AUTO } from "./events-auto.js";

const _curatedIds = new Set(RAW.map(e => e.id));
const _autoMinusDupes = EVENTS_AUTO.filter(e => !_curatedIds.has(e.id));

// Release 02 entries link to /release_2/<file> (served from public/); every
// other relative URL still resolves against the Release 01 war.gov base.
function resolveUrl(e) {
  if (!e.url || e.url.startsWith("http") || e.url.startsWith("/")) return e.url;
  const release = e.release || RELEASE_FOR[e.id] || "Release 01";
  return (release === "Release 02" ? URL_BASE_R2 : URL_BASE) + e.url;
}

export const EVENTS = [...RAW, ..._autoMinusDupes].map(e => ({
  ...e,
  release: e.release || RELEASE_FOR[e.id] || "Release 01",
  url: resolveUrl(e),
}));

export const AGENCY_COLORS = {
  "FBI": "#FF8C42",
  "Department of War": "#7CFFB2",
  "Department of State": "#FFD93D",
  "NASA": "#82B6FF",
  // Release 02 brought CIA / DOE / ODNI into the catalogue. Use the full
  // agency names that match the war.gov canonical column (whipgen scrape
  // produces these strings verbatim), so dropdown options dedupe instead
  // of showing both "DOE" and "Department of Energy".
  "Central Intelligence Agency":                       "#B388FF",
  "Department of Energy":                              "#FFB86B",
  "Office of the Director of National Intelligence":   "#FF6B9D",
  // Release 03 added two more agency strings that appear verbatim in
  // the war.gov canonical CSV: the IC analysis (ICA-UAP-D001) and the
  // congressional/White House correspondence collection (USG-UAP-D001).
  "Intelligence Community":                            "#A8E6CF",
  "U.S. Government":                                   "#D4B8FF",
  // Release 05 introduced the first Executive Office of the President record.
  "Executive Office of the President":                 "#F5A3FF",
};

export const FLAG_LABEL = { anchor: "PRIORITY", high: "ELEVATED", med: "ROUTINE", low: "TRIVIAL" };

// Derived release metadata — used by the LIVE / SEARCH / SEMANTIC headers
// and the App footer so "what releases are catalogued?" doesn't have to be
// hand-updated every time a tranche lands. Just add release-tagged entries
// to RAW (or RELEASE_FOR above) and these update.
export const RELEASES = [...new Set(EVENTS.map(e => e.release))].sort();
export const LATEST_RELEASE = RELEASES[RELEASES.length - 1] || "Release 01";
// "RELEASE 01–02" style label, en-dash between bookends. Single release →
// just that release's name. Used in chrome / banner copy.
export const RELEASES_LABEL = RELEASES.length > 1
  ? `${RELEASES[0]}–${RELEASES[RELEASES.length - 1].replace(/^Release\s+/, "")}`
  : RELEASES[0];
